def __getattr__(name: str):
    if _WARN_LEGACY_API and name in _LAZY_EXPORTS and name not in _STABLE_PUBLIC_API:
        warnings.warn(
            f"{name} remains available for compatibility; prefer matrix_rovib.api",
            DeprecationWarning, stacklevel=2,
        )
    try:
        module_name, attribute = _LAZY_EXPORTS[name]
    except KeyError as exc:
        raise AttributeError(name) from exc
    module = import_module(module_name, 'matrix_rovib') if module_name.startswith(".") else import_module(module_name)
    value = getattr(module, attribute)
    globals()[name] = value
    return value

